def chat_with_model(prompt):
    messages = [
        {"role": "system", "content": "You are a helpful assistant."},
        {"role": "user", "content": prompt}
    ]

    text = tokenizer.apply_chat_template(
        messages,
        tokenize=False,
        add_generation_prompt=True
    )

    model_inputs = tokenizer([text], return_tensors="pt").to(device)

    with torch.no_grad():
        generated_output = model.generate(
            model_inputs.input_ids,
            max_new_tokens=512,
            do_sample=False,
            temperature=0.7,
            top_p=0.95
        )

    generated_ids = [
        output_ids[len(input_ids):]
        for input_ids, output_ids in zip(model_inputs.input_ids, generated_output)
    ]

    response = tokenizer.batch_decode(generated_ids, skip_special_tokens=True)[0]
    return response

def translate_verilog_file(file_path):
    with open(file_path, "r") as file:
        lines = file.readlines()

    for i, verilog_code in enumerate(lines):
        verilog_code = verilog_code.strip()
        if not verilog_code:
            continue  # skip empty lines

        prompt = f"""Translate the following Verilog code to C code. Only output the C code, without any explanations or additional text. Verilog Code: {verilog_code}"""

        print(f"\n--- Translation {i + 1} ---")
        print("Verilog:", verilog_code)

        response = chat_with_model(prompt)
        print("C code:\n", response)

